DROP TABLE time_zone;

CREATE TABLE `time_zone` (
  `zone_id` int(10) NOT NULL AUTO_INCREMENT,
  `country_code` char(2) COLLATE utf8_bin NOT NULL,
  `zone_name` varchar(35) COLLATE utf8_bin NOT NULL,
  PRIMARY KEY (`zone_id`),
  KEY `idx_country_code` (`country_code`),
  KEY `idx_zone_name` (`zone_name`)
) ENGINE=MyISAM AUTO_INCREMENT=425 DEFAULT CHARSET=utf8 COLLATE=utf8_bin;




DROP TABLE timezone;

CREATE TABLE `timezone` (
  `zone_id` int(10) NOT NULL,
  `abbreviation` varchar(6) COLLATE utf8_bin NOT NULL,
  `time_start` decimal(11,0) NOT NULL,
  `gmt_offset` int(11) NOT NULL,
  `dst` char(1) COLLATE utf8_bin NOT NULL,
  KEY `idx_zone_id` (`zone_id`),
  KEY `idx_time_start` (`time_start`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COLLATE=utf8_bin;




DROP TABLE transaction_status;

CREATE TABLE `transaction_status` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `value` varchar(100) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=latin1 COMMENT='Definition of the various transaction status';




DROP TABLE transactions;

CREATE TABLE `transactions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `customer_id` int(11) NOT NULL,
  `description` varchar(333) NOT NULL,
  `credits` decimal(11,6) NOT NULL DEFAULT '0.000000',
  `cost` decimal(11,6) NOT NULL DEFAULT '0.000000',
  `date` datetime NOT NULL,
  `status` varchar(100) NOT NULL DEFAULT 'pending',
  `method` varchar(100) NOT NULL DEFAULT '0',
  `approved_by` int(11) NOT NULL DEFAULT '0',
  `transaction_reference` varchar(400) NOT NULL,
  `gateway_response` varchar(555) NOT NULL,
  `is_earned` int(11) NOT NULL DEFAULT '0',
  `is_shared` int(11) NOT NULL DEFAULT '0',
  `validity` int(11) NOT NULL DEFAULT '0',
  `paid_on` datetime NOT NULL,
  `receiver` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=latin1 COMMENT='Holds details of all purchases on the panel';




DROP TABLE users;

CREATE TABLE `users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `first_name` varchar(100) NOT NULL,
  `last_name` varchar(100) NOT NULL,
  `email` varchar(100) NOT NULL,
  `phone` varchar(100) NOT NULL,
  `address` varchar(122) NOT NULL,
  `city` varchar(111) NOT NULL,
  `state` varchar(111) NOT NULL,
  `country_id` int(11) NOT NULL DEFAULT '0',
  `currency_id` int(11) NOT NULL DEFAULT '0',
  `last_login` varchar(111) NOT NULL,
  `last_ip` varchar(111) NOT NULL,
  `password` varchar(444) NOT NULL,
  `phone_verified` varchar(33) NOT NULL,
  `email_verified` varchar(33) NOT NULL,
  `timezone_id` int(11) NOT NULL DEFAULT '0',
  `default_sender_ID` varchar(22) NOT NULL DEFAULT 'SMSC',
  `facebook_id` varchar(333) NOT NULL,
  `google_id` varchar(333) NOT NULL,
  `photo` varchar(333) NOT NULL DEFAULT 'user.png',
  `language_id` varchar(22) NOT NULL DEFAULT 'en',
  `no_tax` int(11) NOT NULL DEFAULT '0',
  `min_order` varchar(222) NOT NULL DEFAULT '0',
  `role_id` int(11) NOT NULL DEFAULT '4',
  `reseller` int(11) NOT NULL DEFAULT '0',
  `affiliate_id` varchar(33) NOT NULL,
  `referrer` int(11) NOT NULL DEFAULT '0',
  `refered_visits` int(11) NOT NULL DEFAULT '0',
  `date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `api_key` varchar(333) NOT NULL,
  `api_token` varchar(333) NOT NULL,
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=latin1;




DROP TABLE vouchers;

CREATE TABLE `vouchers` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `pin` varchar(20) NOT NULL,
  `credits` decimal(11,2) NOT NULL DEFAULT '0.00',
  `cost` decimal(11,4) NOT NULL DEFAULT '0.0000',
  `used` int(11) NOT NULL DEFAULT '0',
  `date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `validity` int(11) NOT NULL DEFAULT '0',
  `customer_id` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=latin1;




